function changeLang(a){$.ajax({url:"/lib/webservices/hotel-profile-datos-landing-ws.php",data:"lang="+a,type:"POST",success:function(b){var c=jQuery.parseJSON(b),d=c.lang;$("#langSected").empty(),$("#langSected").append(d);var e=c.tagline;$("#tagline").val(e),0==e.length,$("#actualLang").val(a)}})}function checkTagline(){var a=$("#actualLang").val();$.ajax({url:"/lib/webservices/hotel-profile-datos-landing-ws.php",data:"checkTagline=1&langToCheck="+a,type:"POST",success:function(b){var c=jQuery.parseJSON(b);"200"==c.code?($("#circle-"+a).empty(),$("#circle-"+a).append('<i class="fa fa-check-circle-o verde lang-ok">')):$("#circle-"+a).empty()}})}function checkTaglines(){$.ajax({url:"/lib/webservices/hotel-profile-datos-landing-ws.php",data:"checkTaglines=1",type:"POST",success:function(a){var b=jQuery.parseJSON(a);b.forEach(function(a){"200"==a.code?($("#circle-"+a.lang).empty(),$("#circle-"+a.lang).append('<i class="fa fa-check-circle-o verde lang-ok">')):$("#circle-"+a.lang).empty()})}})}$(document).ready(function(){$(".langLia").click(function(a){a.preventDefault()}),$(".validation-form").bootstrapValidator({message:"This value is not valid",feedbackIcons:{valid:"fa fa-check",invalid:"fa fa-exclamation",validating:"fa fa-refresh"},live:"enabled",fields:{tagline:{validators:{noEmpty:{message:"The tagline can\xb4t be empty"}}},landingBg:{validators:{noEmpty:{message:"Please send a background"},file:{extension:"jpeg,png,gif,jpg",type:"image/jpeg,image/png, image/gif, image/jpg",message:"The selected file is not valid"}}}}}),$(".validation-form").bootstrapValidator("validate"),checkTaglines()}),$("#tagline").keyup(function(){var a=$("#tagline").val();$.ajax({url:"/lib/webservices/hotel-profile-datos-landing-ws.php",data:"tagline="+a,type:"POST",success:function(){checkTagline()}})});